<?php $role = $role ?? 'cliente'; $labels = ['cliente' => 'Cliente', 'autonomo' => 'Autônomo', 'empresa' => 'Empresa']; $document = $role === 'empresa' ? 'CNPJ' : 'CPF'; $documentId = strtolower($document); $css = $role === 'cliente' ? 'cadastrocliente' : ($role === 'empresa' ? 'cadastroempresa' : 'cadastroautonomo'); ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Cadastro do <?= htmlspecialchars($labels[$role], ENT_QUOTES, 'UTF-8') ?> — Nexlar</title><link rel="stylesheet" href="/src/css/<?= $css ?>.css"><link rel="stylesheet" href="/src/css/responsive.css"></head><body><div class="toast" id="toast"></div><div class="logo-container"><img src="/src/images/logobranca.png" alt="Nexlar" class="logo-img"></div><main class="card"><div class="card-header"><p class="welcome">Bem-vindos ao Nexlar!</p><h1>Cadastro do <?= htmlspecialchars($labels[$role], ENT_QUOTES, 'UTF-8') ?></h1></div><form data-role="<?= $role ?>"><div class="fields"><div class="field"><label for="nome">Nome completo</label><input type="text" id="nome" placeholder="Nome completo" autocomplete="name" required></div><div class="field"><label for="nascimento">Data de nascimento</label><input type="text" id="nascimento" placeholder="DD/MM/AAAA" inputmode="numeric" autocomplete="bday" oninput="maskDate(this)" maxlength="10" required></div><div class="field"><label for="<?= $documentId ?>"><?= $document ?></label><input type="text" id="<?= $documentId ?>" placeholder="<?= $document === 'CPF' ? '000.000.000-00' : '00.000.000/0000-00' ?>" inputmode="numeric" oninput="<?= $document === 'CPF' ? 'maskCPF(this)' : 'maskCNPJ(this)' ?>" maxlength="<?= $document === 'CPF' ? '14' : '18' ?>" required></div><div class="field"><label for="contato">Contato</label><input type="tel" id="contato" placeholder="(00) 00000-0000" autocomplete="tel" oninput="maskPhone(this)" maxlength="15" required></div><div class="field"><label for="email">E-mail</label><input type="email" id="email" placeholder="E-mail" autocomplete="email" required></div><div class="field"><label for="senha">Senha</label><input type="password" id="senha" placeholder="Senha forte" autocomplete="new-password" required></div><div class="field"><label for="confirmarSenha">Confirmar senha</label><input type="password" id="confirmarSenha" placeholder="Confirmar senha" autocomplete="new-password" required></div></div><div class="terms-wrap"><input type="checkbox" id="termos" required><label for="termos">Aceito os Termos de Uso</label></div><button type="submit" class="btn-continuar" id="btnContinuar">Continuar</button></form></main><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script><script src="/src/js/api.js"></script><script src="/src/js/masks.js"></script><script src="/src/js/auth.js"></script></body></html>

